// BFME stores UnicodeString as the single StringBase<unsigned short> pointer.
// Keep the ownership ABI local while making the forwarding constructors visible
// to the compiler; this is the by-value string shape used by the retail call.
template <typename T> struct StringInlineData
{
	int m_refCount;
	int m_length;
	T m_text[1];
};

template <typename T> class StringBase
{
	friend class UnicodeString;

private:
	StringBase( void ) : m_data( 0 ) {}
	StringBase( const T *text );
	StringBase( const StringBase<T> &other );
	~StringBase();
	void releaseBuffer( void );

	StringInlineData<T> *m_data;
};

class UnicodeString : private StringBase<unsigned short>
{
public:
	UnicodeString( void ) : StringBase<unsigned short>() {}
	UnicodeString( const unsigned short *text )
		: StringBase<unsigned short>( text ) {}
	UnicodeString( const UnicodeString &other )
		: StringBase<unsigned short>( other ) {}
	~UnicodeString() {}

	void format( UnicodeString fmt, ... );
};

struct ICoord2D
{
	Int x;
	Int y;
};

class GameFont;

